-- Moderated classroom stream and complete assignment lifecycle.
create table public.classroom_stream_posts(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,classroom_id uuid not null,
 kind text not null check(kind in ('announcement','discussion')),title text,body text not null check(char_length(trim(body)) between 1 and 10000),
 status text not null default 'published' check(status in ('pending','published','hidden','removed')),pinned boolean not null default false,
 author_id uuid not null references auth.users(id),moderated_by uuid references auth.users(id),moderation_reason text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(school_id,id),foreign key(school_id,classroom_id) references public.learning_classrooms(school_id,id) on delete cascade
);
create table public.classroom_stream_comments(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,post_id uuid not null,body text not null check(char_length(trim(body)) between 1 and 5000),
 status text not null default 'published' check(status in ('pending','published','hidden','removed')),author_id uuid not null references auth.users(id),moderated_by uuid references auth.users(id),moderation_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(school_id,id),foreign key(school_id,post_id) references public.classroom_stream_posts(school_id,id) on delete cascade
);
alter table public.assignments add column classroom_id uuid,add column allow_late boolean not null default false,add column published_at timestamptz,add column closed_at timestamptz,add column released_at timestamptz,add column released_by uuid references auth.users(id),add constraint assignments_classroom_fk foreign key(school_id,classroom_id) references public.learning_classrooms(school_id,id) on delete restrict;
alter table public.assignments drop constraint if exists assignments_status_check;
alter table public.assignments add constraint assignments_status_check check(status in ('draft','published','closed','released','archived'));
alter table public.assignment_submissions add column effective_due_at timestamptz,add column late boolean not null default false,add column graded_at timestamptz,add column released_at timestamptz;
alter table public.assignment_submissions drop constraint if exists assignment_submissions_status_check;
alter table public.assignment_submissions add constraint assignment_submissions_status_check check(status in ('draft','submitted','late','graded','returned','released'));
create table public.assignment_extensions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,assignment_id uuid not null,student_id uuid not null,extended_due_at timestamptz not null,reason text not null,granted_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(assignment_id,student_id),unique(school_id,id),foreign key(school_id,assignment_id) references public.assignments(school_id,id) on delete cascade,foreign key(school_id,student_id) references public.students(school_id,id) on delete cascade);
create table public.assignment_attachments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,assignment_id uuid,submission_id uuid,owner_id uuid not null references auth.users(id),original_name text not null,storage_path text not null,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 20971520),created_at timestamptz not null default now(),unique(storage_path),unique(school_id,id),foreign key(school_id,assignment_id) references public.assignments(school_id,id) on delete cascade,foreign key(school_id,submission_id) references public.assignment_submissions(school_id,id) on delete cascade,check((assignment_id is null)<>(submission_id is null)));
create table public.assignment_events(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,assignment_id uuid not null,submission_id uuid,event_type text not null,note text,actor_id uuid not null references auth.users(id),metadata jsonb not null default '{}',occurred_at timestamptz not null default now(),foreign key(school_id,assignment_id) references public.assignments(school_id,id) on delete cascade,foreign key(school_id,submission_id) references public.assignment_submissions(school_id,id) on delete cascade);
do $$ declare t text;begin foreach t in array array['classroom_stream_posts','classroom_stream_comments','assignment_extensions','assignment_attachments','assignment_events'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I_read on public.%I for select to authenticated using(public.is_school_member(school_id))',t,t);end loop;end$$;
grant select on public.classroom_stream_posts,public.classroom_stream_comments,public.assignment_extensions,public.assignment_attachments,public.assignment_events to authenticated,service_role;grant insert,update,delete on public.classroom_stream_posts,public.classroom_stream_comments,public.assignment_extensions,public.assignment_attachments,public.assignment_events to service_role;

create or replace function public.manage_stream_post(_school uuid,_classroom uuid,_post uuid,_kind text,_title text,_body text,_action text,_reason text,_actor uuid) returns public.classroom_stream_posts language plpgsql security definer set search_path='' as $$
declare _row public.classroom_stream_posts;_teacher boolean;begin _teacher:=public.can_edit_classroom(_school,_classroom,_actor);
if _action='create' then if not exists(select 1 from public.learning_classroom_memberships where school_id=_school and classroom_id=_classroom and active and (user_id=_actor or student_id in(select id from public.students where user_id=_actor))) then raise exception 'Not a classroom member.' using errcode='42501';end if;insert into public.classroom_stream_posts(school_id,classroom_id,kind,title,body,status,author_id,published_at) values(_school,_classroom,_kind,nullif(trim(_title),''),trim(_body),case when _teacher then 'published' else 'pending' end,_actor,case when _teacher then now() end) returning * into _row;
else if not _teacher then raise exception 'Classroom moderation permission required.' using errcode='42501';end if;update public.classroom_stream_posts set status=case _action when 'approve' then 'published' when 'hide' then 'hidden' else 'removed' end,moderated_by=_actor,moderation_reason=nullif(trim(_reason),''),published_at=case when _action='approve' then coalesce(published_at,now()) else published_at end where school_id=_school and id=_post and classroom_id=_classroom returning * into _row;end if;
insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,metadata) values(_school,_actor,'classroom.stream.'||_action,'stream_post',_row.id,jsonb_build_object('classroomId',_classroom,'reason',_reason));return _row;end$$;
create or replace function public.transition_assignment(_school uuid,_assignment uuid,_action text,_actor uuid) returns public.assignments language plpgsql security definer set search_path='' as $$ declare _row public.assignments;begin select * into _row from public.assignments where school_id=_school and id=_assignment for update;if _row.id is null or not public.can_edit_classroom(_school,_row.classroom_id,_actor) then raise exception 'Assignment unavailable.' using errcode='42501';end if;if _action='publish' and _row.status='draft' then update public.assignments set status='published',published_at=now() where id=_assignment returning * into _row;elsif _action='close' and _row.status='published' then update public.assignments set status='closed',closed_at=now() where id=_assignment returning * into _row;elsif _action='release' and _row.status in('published','closed') then update public.assignments set status='released',released_at=now(),released_by=_actor where id=_assignment returning * into _row;update public.assignment_submissions set status='released',released_at=now() where assignment_id=_assignment and status='graded';else raise exception 'Invalid assignment transition.' using errcode='23514';end if;insert into public.assignment_events(school_id,assignment_id,event_type,actor_id) values(_school,_assignment,_action,_actor);return _row;end$$;
create or replace function public.submit_assignment(_school uuid,_assignment uuid,_student uuid,_response jsonb,_submit boolean,_actor uuid) returns public.assignment_submissions language plpgsql security definer set search_path='' as $$ declare _a public.assignments;_due timestamptz;_row public.assignment_submissions;begin select * into _a from public.assignments where school_id=_school and id=_assignment and status in('published','closed');if _a.id is null or not exists(select 1 from public.students where school_id=_school and id=_student and user_id=_actor and class_id=_a.class_id) then raise exception 'Assignment unavailable.' using errcode='42501';end if;select coalesce((select extended_due_at from public.assignment_extensions where assignment_id=_assignment and student_id=_student),_a.due_at) into _due;if _submit and _due is not null and now()>_due and not _a.allow_late then raise exception 'The submission deadline has passed.' using errcode='23514';end if;insert into public.assignment_submissions(school_id,assignment_id,student_id,response,status,submitted_at,effective_due_at,late) values(_school,_assignment,_student,_response,case when _submit then case when _due is not null and now()>_due then 'late' else 'submitted' end else 'draft' end,case when _submit then now() end,_due,_submit and _due is not null and now()>_due) on conflict(assignment_id,student_id) do update set response=excluded.response,status=excluded.status,submitted_at=excluded.submitted_at,effective_due_at=excluded.effective_due_at,late=excluded.late where public.assignment_submissions.status in('draft','returned') returning * into _row;if _row.id is null then raise exception 'Submission is no longer editable.' using errcode='23514';end if;return _row;end$$;
revoke all on function public.manage_stream_post(uuid,uuid,uuid,text,text,text,text,text,uuid),public.transition_assignment(uuid,uuid,text,uuid),public.submit_assignment(uuid,uuid,uuid,jsonb,boolean,uuid) from public,anon,authenticated;grant execute on function public.manage_stream_post(uuid,uuid,uuid,text,text,text,text,text,uuid),public.transition_assignment(uuid,uuid,text,uuid),public.submit_assignment(uuid,uuid,uuid,jsonb,boolean,uuid) to service_role;
